package finance.network;

import finance.insurance.*;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.fml.DistExecutor;
import net.minecraftforge.network.NetworkEvent;
import java.util.*;import java.util.function.Supplier;

public record InsuranceResponsePacket(long requestId,boolean admin,long poolCash,long exposure,long unpaid,List<PolicyRow>policies,List<ClaimRow>claims,CompanyRiskService.Summary risk){public static final int MAX_ROWS=128;public record PolicyRow(UUID id,InsuranceProduct product,UUID companyId,UUID objectId,PolicyStatus status,long effective,long expiry,long coverage,long remaining,long premium){}public record ClaimRow(UUID id,UUID policyId,UUID eventId,ClaimStatus status,long loss,long approved,long paid,String reason){}public InsuranceResponsePacket{if(requestId<=0)throw new IllegalArgumentException();policies=bounded(policies);claims=bounded(claims);}private static<T>List<T>bounded(List<T>x){return x==null?List.of():List.copyOf(x.subList(0,Math.min(MAX_ROWS,x.size())));}public static void encode(InsuranceResponsePacket p,FriendlyByteBuf b){b.writeLong(p.requestId);b.writeBoolean(p.admin);b.writeLong(p.poolCash);b.writeLong(p.exposure);b.writeLong(p.unpaid);b.writeVarInt(p.policies.size());for(var r:p.policies){b.writeUUID(r.id);b.writeEnum(r.product);b.writeBoolean(r.companyId!=null);if(r.companyId!=null)b.writeUUID(r.companyId);b.writeUUID(r.objectId);b.writeEnum(r.status);b.writeLong(r.effective);b.writeLong(r.expiry);b.writeLong(r.coverage);b.writeLong(r.remaining);b.writeLong(r.premium);}b.writeVarInt(p.claims.size());for(var r:p.claims){b.writeUUID(r.id);b.writeUUID(r.policyId);b.writeUUID(r.eventId);b.writeEnum(r.status);b.writeLong(r.loss);b.writeLong(r.approved);b.writeLong(r.paid);b.writeUtf(r.reason,256);}var r=p.risk;b.writeLong(r.cash());b.writeLong(r.inventoryValue());b.writeDouble(r.largestInventoryPercent());b.writeLong(r.loanBalance());b.writeLong(r.futuresEquity());b.writeLong(r.insuredInventory());b.writeLong(r.uninsuredInventory());b.writeLong(r.pendingClaims());b.writeUtf(r.hedgeStatus(),32);b.writeUtf(r.level(),16);b.writeUtf(r.reasons(),256);}public static InsuranceResponsePacket decode(FriendlyByteBuf b){long id=b.readLong();boolean admin=b.readBoolean();long cash=b.readLong(),exposure=b.readLong(),unpaid=b.readLong();int n=count(b);List<PolicyRow>policies=new ArrayList<>(n);for(int i=0;i<n;i++){UUID pid=b.readUUID();InsuranceProduct p=b.readEnum(InsuranceProduct.class);UUID company=b.readBoolean()?b.readUUID():null;policies.add(new PolicyRow(pid,p,company,b.readUUID(),b.readEnum(PolicyStatus.class),b.readLong(),b.readLong(),b.readLong(),b.readLong(),b.readLong()));}n=count(b);List<ClaimRow>claims=new ArrayList<>(n);for(int i=0;i<n;i++)claims.add(new ClaimRow(b.readUUID(),b.readUUID(),b.readUUID(),b.readEnum(ClaimStatus.class),b.readLong(),b.readLong(),b.readLong(),b.readUtf(256)));var risk=new CompanyRiskService.Summary(b.readLong(),b.readLong(),b.readDouble(),b.readLong(),b.readLong(),b.readLong(),b.readLong(),b.readLong(),b.readUtf(32),b.readUtf(16),b.readUtf(256));return new InsuranceResponsePacket(id,admin,cash,exposure,unpaid,policies,claims,risk);}private static int count(FriendlyByteBuf b){int n=b.readVarInt();if(n<0||n>MAX_ROWS)throw new IllegalArgumentException("insurance rows");return n;}public static void handle(InsuranceResponsePacket p,Supplier<NetworkEvent.Context>s){var c=s.get();c.enqueueWork(()->DistExecutor.unsafeRunWhenOn(Dist.CLIENT,()->()->finance.client.InsuranceClientCache.accept(p)));c.setPacketHandled(true);}}
